@group(0) @binding(3) var<uniform> params : Params;

@compute @workgroup_size(1, 1, 1)
@override_required(WORKGROUP_SIZE = 1)
fn main(@builtin(global_invocation_id) global_id : vec3<u32>) {
  let i : u32 = global_id.x;
  if (i >= params.length) {
    return;
  }
  let x : f32 = left_values[i];
  let y : f32 = right_values[i];
  let abs_x : f32 = abs(x);
  let divisor : f32 = 1.0 + abs_x;
  let result : f32 = x / divisor;
  output_values[params.output_offset + i] = result;
}

